<?php require_once '../config/auth.php';require_once '../config/database.php';require_once '../config/layout.php';require_role('pelamar');$rows=$pdo->query("SELECT l.*,d.nama_divisi FROM lowongan l JOIN divisi d ON d.id_divisi=l.id_divisi WHERE l.status='Dipublikasikan' AND (l.deadline IS NULL OR l.deadline>=CURDATE()) ORDER BY l.tanggal_publish DESC")->fetchAll();page_header('Lowongan Aktif');?><div class="grid"><?php foreach($rows as $r):?><div class="card"><h2><?=e($r['judul_lowongan'])?></h2><p><?=e($r['nama_divisi'])?></p><p>Kebutuhan: <?=e($r['jumlah_kebutuhan'])?></p><p>Deadline: <?=e($r['deadline']?:'-')?></p><a class="btn" href="detail_lowongan.php?id=<?=$r['id_lowongan']?>">Lihat Detail</a></div><?php endforeach;if(!$rows):?><div class="card">Belum ada lowongan aktif.</div><?php endif;?></div><?php page_footer();
